// Verify withdrawal cannot leave an already published report looking usable.
test("withdrawal invalidates exactly the dependent reports and preserves the source block after reload", () => {
  const initial = createMobileState();
  const state = withdrawSource(initial);
  assert.equal(state.reports.filter((r) => r.stale).length, 3);
  assert.equal(reportDocuments("全部领域", state.withdrawn).length, 11);
  assert.equal(state.reports.find((r) => r.scope === "消费权益")?.stale, false);
  assert.equal(parseMobileState(JSON.stringify(state)).withdrawn, true);
  assert.equal(withdrawSource(state), state);
});

// Check the publication gate requires a rebuilt, reviewed version after source loss.
test("invalidated reports require rebuilding and a fresh human approval", () => {
  const state = withdrawSource(createMobileState());
  const id = state.reports[0].id;
  assert.equal(approveReport(state, id, true).reports[0].status, "待审核");
  const rebuilt = rebuildReport(state, id);
  assert.equal(rebuilt.withdrawn, true);
  assert.equal(rebuilt.reports[0].revision, 2);
  assert.equal(
    rebuilt.reports[0].evidenceIds.includes(controlledDocument),
    false,
  );
  assert.equal(rebuilt.reports[0].stale, false);
  assert.equal(approveReport(rebuilt, id, false).reports[0].status, "待审核");
  assert.equal(approveReport(rebuilt, id, true).reports[0].status, "已发布");
});

// Empty notes must not create review records or change risk decisions.
test("review requires a valid risk and a meaningful note", () => {
  const state = createMobileState();
  assert.equal(
    submitReview(state, "ALT-1103-001", "通过复核", "     ", "16:00"),
    state,
  );
  assert.equal(
    submitReview(state, "missing", "通过复核", "已核查相关材料", "16:00"),
    state,
  );
  for (const [result, status] of [
    ["通过复核", "已确认"],
    ["补充材料", "复核中"],
    ["排除线索", "已归档"],
  ] as const) {
    const next = submitReview(
      state,
      "ALT-1103-001",
      result,
      "  已核查相关材料  ",
      "16:00",
    );
    assert.equal(next.statuses["ALT-1103-001"], status);
    assert.equal(next.reviews[0].note, "已核查相关材料");
  }
});

